<style>*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 20% 10%,#17275a 0,#0b1020 34%,#05070d 100%);color:#fff;font-family:Inter,system-ui,-apple-system,sans-serif;display:grid;place-items:center;padding:24px}.wrap{width:min(560px,100%)}.brand{display:flex;align-items:center;gap:10px;margin-bottom:18px;color:#9edcff;font-weight:700}.brand b{color:#fff}.card{border:1px solid rgba(255,255,255,.12);background:rgba(10,15,29,.78);backdrop-filter:blur(18px);border-radius:28px;padding:28px;box-shadow:0 30px 90px rgba(0,0,0,.4)}h1{font-size:30px;margin:0 0 8px}.desc{color:#aab5ca;margin:0 0 24px;line-height:1.55}.amounts{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:10px 0 18px}.amounts button,.submit{border:0;border-radius:12px;padding:12px;background:#151d31;color:#dce8ff;cursor:pointer}.amounts button:hover{background:#202d4b}.field{margin:14px 0}.field label{display:block;font-size:13px;color:#9da9bd;margin-bottom:7px}.field input,.field textarea{width:100%;border:1px solid rgba(255,255,255,.12);background:#0a1020;color:#fff;border-radius:14px;padding:13px 14px;outline:none}.field textarea{min-height:110px;resize:vertical}.captcha{margin:16px 0;display:flex;justify-content:center;min-height:65px}.submit{width:100%;background:linear-gradient(90deg,#1677ff,#8a4dff);font-size:16px;font-weight:700;padding:15px}.submit:disabled{opacity:.6}.note{font-size:12px;color:#71809a;text-align:center;margin-top:14px}.status{display:none;margin-top:16px;padding:12px;border-radius:12px;background:#101b30;color:#cfe0ff}.status.show{display:block}.footer{font-size:12px;color:#65738a;text-align:center;margin-top:16px}</style><link rel="stylesheet" href="/assets/evruni-design-system.css?v=1"></head><body><main class="wrap"><div class="brand">✦ <span><b>Evruni</b> Direct Donations</span></div><section class="card"><h1><?=htmlspecialchars((string)$p['title'],ENT_QUOTES,'UTF-8')?></h1><p class="desc"><?=nl2br(htmlspecialchars((string)$p['description'],ENT_QUOTES,'UTF-8'))?></p><form id="donateForm"><input type="hidden" name="slug" value="<?=htmlspecialchars((string)$p['slug'],ENT_QUOTES,'UTF-8')?>"><div class="field"><label>Сумма, <?=htmlspecialchars((string)$p['currency'],ENT_QUOTES,'UTF-8')?></label><input id="amount" name="amount" type="number" min="<?=htmlspecialchars((string)$p['min_amount'],ENT_QUOTES,'UTF-8')?>" <?=($p['max_amount']!==null?'max="'.htmlspecialchars((string)$p['max_amount'],ENT_QUOTES,'UTF-8').'"':'')?> step="0.01" required></div><div class="amounts"><?php foreach([5,10,25,50] as $v): ?><button type="button" data-amount="<?=$v?>"><?=$v?></button><?php endforeach; ?></div><div class="field"><label>Имя</label><input name="name" maxlength="80" placeholder="Аноним"></div><div class="field"><label>Сообщение стримеру</label><textarea name="message" maxlength="500" placeholder="Напиши что-нибудь хорошее ❤️"></textarea></div><?php if($captchaEnabled): ?><div class="captcha"><div class="cf-turnstile" data-sitekey="<?=htmlspecialchars($turnstileSiteKey,ENT_QUOTES,'UTF-8')?>" data-theme="dark"></div></div><?php endif; ?><button class="submit" id="submit" type="submit">💜 Поддержать стримера</button></form><div class="status" id="status"></div><div class="note">Evruni не принимает и не хранит деньги. После создания заявки вы переходите напрямую на платёжную страницу, указанную стримером.</div></section><div class="footer">Evruni Creator Tools</div></main>
<script>const f=document.getElementById('donateForm'),a=document.getElementById('amount'),s=document.getElementById('status'),captchaEnabled=<?= $captchaEnabled?'true':'false' ?>;document.querySelectorAll('[data-amount]').forEach(b=>b.onclick=()=>a.value=b.dataset.amount);f.onsubmit=async e=>{e.preventDefault();const btn=document.getElementById('submit');btn.disabled=true;s.className='status show';if(captchaEnabled&&(!window.turnstile||!turnstile.getResponse())){s.textContent='Подтверди проверку безопасности.';btn.disabled=false;return}const body=Object.fromEntries(new FormData(f).entries());if(captchaEnabled)body.turnstile=turnstile.getResponse();try{const r=await fetch('/api/donation_intent.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Ошибка');s.textContent='Заявка создана. Сейчас откроется оплата.';if(d.payment_url)location.href=d.payment_url;else s.textContent='У стримера пока не настроена платёжная ссылка.'}catch(err){s.textContent=err.message;btn.disabled=false}};</script></body></html>
